import{_ as a}from"./chunks/architecture.Cs8uKTTN.js";import{_ as e,o as r,c as o,a2 as d}from"./chunks/framework.CHeM0PsO.js";const P=JSON.parse('{"title":"swag2mcp","description":"","frontmatter":{},"headers":[],"relativePath":"ko/index.md","filePath":"ko/index.md","lastUpdated":1784903584000}'),s={name:"ko/index.md"};function n(i,t,c,l,p,h){return r(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="swag2mcp" tabindex="-1">swag2mcp <a class="header-anchor" href="#swag2mcp" aria-label="Permalink to &quot;swag2mcp&quot;">​</a></h1><div style="background:#dc2626;color:white;padding:20px 24px;border-radius:12px;text-align:center;font-size:1.4em;font-weight:700;margin:24px 0;"> 🚧 작업 진행 중 — 출시 예정! </div><p>OpenAPI/Swagger/Postman API 명세를 Model Context Protocol(MCP)을 통해 LLM 에이전트와 연결합니다.</p><a href="https://www.youtube.com/watch?v=1Da4UmE2f9U" target="_blank"><img src="https://raw.githubusercontent.com/mmadfox/swag2mcp/main/docs/cover.png" alt="Preview"></a><h2 id="당신의-api가-llm과-대화합니다" tabindex="-1">당신의 API가 LLM과 대화합니다 <a class="header-anchor" href="#당신의-api가-llm과-대화합니다" aria-label="Permalink to &quot;당신의 API가 LLM과 대화합니다&quot;">​</a></h2><p>한 줄의 설정으로 모든 OpenAPI/Swagger/Postman 파일을 MCP 서버로 변환합니다. LLM 에이전트가 API를 발견, 검사, 호출합니다 — 통합 코드가 전혀 필요 없습니다.</p><img src="'+a+'" width="700" alt="swag2mcp architecture"><h2 id="래퍼를-작성하지-마세요" tabindex="-1">래퍼를 작성하지 마세요 <a class="header-anchor" href="#래퍼를-작성하지-마세요" aria-label="Permalink to &quot;래퍼를 작성하지 마세요&quot;">​</a></h2><p>새 API를 LLM에 연결할 때마다 동일한 보일러플레이트를 작성합니다: 명세 파싱, 인증, 오류 처리, 속도 제한. swag2mcp가 대신 처리합니다 — 19개의 즉시 사용 가능한 MCP 도구.</p><h2 id="이런-분들에게-필요합니다" tabindex="-1">이런 분들에게 필요합니다 <a class="header-anchor" href="#이런-분들에게-필요합니다" aria-label="Permalink to &quot;이런 분들에게 필요합니다&quot;">​</a></h2><table tabindex="0"><thead><tr><th>역할</th><th>이유</th></tr></thead><tbody><tr><td><strong>AI 에이전트 개발자</strong></td><td>2일이 아닌 2분 만에 API 연결</td></tr><tr><td><strong>MCP 엔지니어</strong></td><td>핸들러 코드 불필요 — 명세만 가리키면 됩니다</td></tr><tr><td><strong>아키텍트</strong></td><td>회사 내 모든 LLM을 위한 단일 API 통합 레이어</td></tr><tr><td><strong>데이터 분석가</strong></td><td>코딩 없이 자연어로 API 접근</td></tr><tr><td><strong>DevOps / SRE</strong></td><td>추가 서비스 없이 LLM을 통한 모니터링 및 자동화</td></tr><tr><td><strong>통합 엔지니어</strong></td><td>Basic부터 OAuth2, HMAC까지 9가지 인증 방식 기본 제공</td></tr><tr><td><strong>QA 엔지니어</strong></td><td>실제 API 없이 격리된 테스트를 위한 모의 서버</td></tr><tr><td><strong>제품 관리자</strong></td><td>백엔드 작업 없이 빠른 AI 기능 프로토타입</td></tr><tr><td><strong>그 외 많은 분들</strong></td><td></td></tr></tbody></table><hr><h2 id="라이선스" tabindex="-1">라이선스 <a class="header-anchor" href="#라이선스" aria-label="Permalink to &quot;라이선스&quot;">​</a></h2><p><strong>GNU Affero General Public License v3.0</strong>(AGPL v3)에 따라 라이선스가 부여됩니다.</p><p>전체 라이선스 텍스트는 <a href="https://github.com/mmadfox/swag2mcp/blob/main/LICENSE" target="_blank" rel="noreferrer">LICENSE</a>를 참조하세요.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SPDX-License-Identifier: AGPL-3.0-only</span></span></code></pre></div>',16)])])}const b=e(s,[["render",n]]);export{P as __pageData,b as default};
